def load(name):return json.loads((OUT/name).read_text(encoding='utf-8-sig'))
def pct(x):return f'{100*x:.1f}%'
def ci(v):return pct(v[0])+'–'+pct(v[1])
def compact(rows):
    grouped=collections.defaultdict(list)
    for rid in sorted(set(rows)):
        m=re.fullmatch(r'(PCF-[A-Z]+)-(\d+)',rid)
        if m:grouped[m[1]].append(int(m[2]))
    out=[]
    for prefix,ns in grouped.items():
        runs=[];a=b=ns[0]
        for n in ns[1:]:
            if n==b+1:b=n
            else:runs.append(f'{a:03}' if a==b else f'{a:03}–{b:03}');a=b=n
        runs.append(f'{a:03}' if a==b else f'{a:03}–{b:03}')
        out.append(prefix+' '+', '.join(runs))
    return '; '.join(out)

def unnamed_review():
    summary=load('unnamed-summary-v2.json');rows=csvrows(OUT/'unnamed-search-v2.csv');idx=page_index()
    old={tuple(r[k] for k in ['family','source_id','pdf_page','line']):r for r in csvrows(OUT/'unnamed-line-review.csv')}
    out=[];access=[]
    for r in rows:
        if r['result']!='registration-shaped occurrence':continue
        key=tuple(r[k] for k in ['family','source_id','pdf_page','line'])
        if key in old:assessment=old[key]['line_assessment']
        else:
            # Inspect the immediate line only, and emit no source fragment.
            line=idx[r['source_id'],int(r['pdf_page'])][0].read_text(encoding='utf-8-sig',errors='replace').splitlines()[int(r['line'])-1]
            exact=re.sub(r'[\s-]','',r['registration']).casefold() in re.sub(r'[\s-]','',line).casefold()
            assessment='complete composite registration occurs on the immediate line' if exact else 'registration-shaped occurrence; identity not established'
            access.append({'source_id':r['source_id'],'pdf_page':r['pdf_page'],'line':r['line'],'family':r['family'],'access':'Registration on immediate line only; no page description or image.'})
        out.append(dict(r,line_assessment=assessment))
    savecsv('unnamed-line-review-v2.csv',out,list(out[0]))
    statuses=[]
    for r in summary['results']:
        hits=[x for x in rows if x['family']==r['family'] and x['result']=='registration-shaped occurrence']
        statuses.append({'family':r['family'],'registration':r['registration'],'result':r['result'],'occurrences':len(hits),'occurs_on_page_logged_read_by_extraction':any(x['source_page_read_by_extraction']=='yes' for x in hits) if r['registration'] else None,'occurs_on_page_not_logged_read_by_extraction':any(x['source_page_read_by_extraction']=='no' for x in hits) if r['registration'] else None,'candidate_pages_without_text':len(r.get('candidate_pages_without_text',[]))})
    save('unnamed-read-status-v2.json',{'families':statuses,'new_immediate_line_access':access,'interpretation':'A registration-shaped number on a logged page is a search occurrence, not an independently established object identity. Composite identifiers are assessed separately from short bare numbers. Negative results cover available held text only.'})
    print('UNNAMED new line review',access)

def write_reports():
    blind=load('blind-summary.json');om=load('omission-summary.json');count=load('count-check-v2.json');oldcount=load('count-check.json');initial=load('initial-results-2026-10-21/count-check.json');join=load('coordinator-join-check-v2.json');oldjoin=load('coordinator-join-check.json');loc=load('locator-check-v2.json');con=load('content-check-v2.json');oldcon=load('content-check.json');unnamed=load('unnamed-read-status-v2.json');manifest=load('input-manifest-v2.json')
    current=count['recomputed_total'];prev=oldcount['recomputed_total'];first=initial['recomputed_total']
    failures=join['coordinator_would_not_reach'];candidate=[x for x in join['selected_coordinator_assessments'] if x['candidate_conflicts']];extra=join['supplemental_candidate_objections']
