    locator=f"The revised locator audit checks {loc['primary_page_locators_checked']} primary page locators, {loc['secondary_references_checked']} secondary references, {loc['family_memberships_checked']} family memberships, {loc['context_family_memberships_checked']} separate context-family memberships and {loc['baseline_rows_checked']} baseline rows. Every primary page has non-empty held text. Every family exists at its explicit local_site_label, each matched row names one family, and no unflagged pair of rows matches the same family. Baseline numbers are checked only in cisi_in_baseline or other_numbers. There are zero locator or identifier failures in both the preserved final first audit and v2."
    content=f"Git lists {con['tracked_files_scanned']} tracked files in this package. The supplementary revised working-tree scan covers {con['files_scanned']} text artifacts and samples 200 distinct 13-word windows for each of {len(con['source_coverage'])} cited sources, {sum(x['sampled_unique_windows'] for x in con['source_coverage'])} windows total, using seed 20261023. Both the first and revised scans record 96 raw coordinates. The revised classification is 66 numeric-table coincidences, 24 publication-title citations in bibliographic identity metadata and six vocabulary hits in safety wording. These classifications distinguish raw matches from copied object prose; no sampled hit establishes copied object description. There is no numeric-unit or populated excluded-field hit. R01–R13 refer in order to check 6 of CODEX-PROMPT-4.md, R14 is its unit pattern, R15 an excluded populated field and R16 a 13-word match. Every coordinate is retained without its source text. This sampled check does not cover unsampled windows."
    def hit_locations(c):
        locations=collections.Counter((h['file'].replace('\\','/').split('2026-10-21-post-catalogue-finds/')[-1],h['line'],h['category'],h.get('classification','raw match')) for h in c['hits'])
        return '; '.join(f'{f}:{line}, {cat}, {label}'+(f' ×{n}' if n>1 else '') for (f,line,cat,label),n in sorted(locations.items()))+'.'
    locations='The revised content-hit locations are '+hit_locations(con)
    coords=lambda c:collections.Counter((h['file'],h['line'],h['category']) for h in c['hits'])
    oldlocations='The first raw content-hit coordinates are identical to the revised coordinates above. Its original source-window classifications remain preserved; v2 classifies them by numeric or bibliographic use.' if coords(con)==coords(oldcon) else 'The first content-hit locations are '+hit_locations(oldcon)
    us=unnamed['families'];found=[r for r in us if r['result']=='found'];notfound=[r for r in us if r['result']=='not found'];noreg=[r for r in us if r['result']=='no registration supplied']
    search=f"The unnamed-family search covers all 39 current rows, including 20 with registrations. V2 corrects punctuation handling in composite identifiers and yields {len(found)} positive family searches with {sum(r['occurrences'] for r in found)} occurrence coordinates, {len(notfound)} negative searches and {len(noreg)} rows without a registration. The first endpoint had eight positive family searches and 69 coordinates. The added complete composite registration is family 5255, NT18/T5/1479. Short bare numbers can coincide with pagination or tabular values, so a search occurrence does not establish an omitted physical object. Immediate-line classifications and page-read flags are preserved in unnamed-line-review-v2.csv and unnamed-read-status-v2.json. Negative results cover held text; candidate pages without text are listed per family in unnamed-summary-v2.json."
    found_text='Registration-shaped occurrences on pages logged read by extraction: '+', '.join(f"{r['family']} ({r['registration']})" for r in found if r['occurs_on_page_logged_read_by_extraction'])+'.'
    unread=[r for r in found if not r['occurs_on_page_logged_read_by_extraction']]
