    us_table=['| Family | Registration | Search result | On a page logged read |','|---|---|---|---|']
    for r in us:us_table.append(f"| {r['family']} | {r['registration'] or '—'} | {r['result']} | {'yes' if r['occurs_on_page_logged_read_by_extraction'] else ('no' if r['registration'] else 'not applicable')} |")
